INSERT INTO resultados_aprendizaje (idMateria, orden, texto) VALUES
(41, 1, 'Selecciona los componentes de integración de un equipo microinformático estándar, describiendo sus funciones y comparando prestaciones de distintos fabricantes.'),
(41, 2, 'Ensambla un equipo microinformático, interpretando planos e instrucciones del fabricante aplicando técnicas de montaje.'),
(41, 3, 'Mide parámetros eléctricos, identificando el tipo de señal y relacionándola con sus unidades características.'),
(41, 4, 'Mantiene equipos informáticos interpretando las recomendaciones de los fabricantes y relacionando las disfunciones con sus causas.'),
(41, 5, 'Instala software en un equipo informático utilizando una imagen almacenada en un soporte de memoria y justificando el procedimiento a seguir.'),
(41, 6, 'Reconoce nuevas tendencias en el ensamblaje de equipos microinformáticos describiendo sus ventajas y adaptándolas a las características de uso de los equipos.'),
(41, 7, 'Mantiene periféricos, interpretando las recomendaciones de los fabricantes de equipos y relacionando disfunciones con sus causas.'),
(41, 8, 'Cumple las normas de prevención de riesgos laborales y de protección ambiental, identificando los riesgos asociados, las medidas y equipos para prevenirlos.');
INSERT INTO resultados_aprendizaje (idMateria, orden, texto) VALUES
(25, 1, 'Instala y actualiza aplicaciones ofimáticas, interpretando especificaciones y describiendo los pasos a seguir en el proceso.'),
(25, 2, 'Elabora documentos y plantillas, describiendo y aplicando las opciones avanzadas de procesadores de textos.'),
(25, 3, 'Elabora documentos y plantillas de cálculo, describiendo y aplicando opciones avanzadas de hojas de cálculo.'),
(25, 4, 'Elabora documentos con bases de datos ofimáticas describiendo y aplicando operaciones de manipulación de datos.'),
(25, 5, 'Manipula imágenes digitales analizando las posibilidades de distintos programas y aplicando técnicas de captura y edición básicas.'),
(25, 6, 'Manipula secuencias de vídeo analizando las posibilidades de distintos programas y aplicando técnicas de captura y edición básicas.'),
(25, 7, 'Elabora presentaciones multimedia describiendo y aplicando normas básicas de composición y diseño.'),
(25, 8, 'Realiza operaciones de gestión del correo y la agenda electrónica, relacionando necesidades de uso con su configuración.'),
(25, 9, 'Aplica técnicas de soporte en el uso de aplicaciones, identificando y resolviendo incidencias.');
INSERT INTO resultados_aprendizaje (idMateria, orden, texto) VALUES
(4, 1, 'Reconoce la estructura de redes locales cableadas analizando las características de entornos de aplicación y describiendo la funcionalidad de sus componentes.'),
(4, 2, 'Despliega el cableado de una red local interpretando especificaciones y aplicando técnicas de montaje.'),
(4, 3, 'Interconecta equipos en redes locales cableadas describiendo estándares de cableado y aplicando técnicas de montaje de conectores.'),
(4, 4, 'Instala equipos en red, describiendo sus prestaciones y aplicando técnicas de montaje.'),
(4, 5, 'Mantiene una red local interpretando recomendaciones de los fabricantes de hardware o software y estableciendo la relación entre disfunciones y sus causas.'),
(4, 6, 'Cumple las normas de prevención de riesgos laborales y de protección ambiental, identificando los riesgos asociados, las medidas y equipos para prevenirlos.');
INSERT INTO resultados_aprendizaje (idMateria, orden, texto) VALUES
(26, 1, 'Reconoce las características de los sistemas de archivo, describiendo sus tipos y aplicaciones.'),
(26, 2, 'Instala sistemas operativos, relacionando sus características con el hardware del equipo y el software de aplicación.'),
(26, 3, 'Realiza tareas básicas de configuración de sistemas operativos, interpretando requerimientos y describiendo los procedimientos seguidos.'),
(26, 4, 'Realiza operaciones básicas de administración de sistemas operativos, interpretando requerimientos y optimizando el sistema para su uso.'),
(26, 5, 'Crea máquinas virtuales identificando su campo de aplicación e instalando software específico.');
